from fastapi import FastAPI
from pydantic import BaseModel
from fastapi.openapi.utils import get_openapi
import json

class ModelA(BaseModel):
    a: str

class ModelB(BaseModel):
    b: str

app = FastAPI(
    responses={
        500: {
            'model': ModelA | ModelB,
            'content': {"application/json": {
                'examples': {"Case A": {"value": "a"}}
            }}
        }
    }
)

@app.get('/route1')
def route1():
    return "test"

@app.get('/route2')
def route2():
    return "test"

@app.get('/route3')
def route3():
    return "test"

def test_openapi_duplication():
    openapi_schema = get_openapi(
        title=app.title,
        version=app.version,
        routes=app.routes,
    )

    for path, methods in openapi_schema["paths"].items():
        for method, operation in methods.items():
            response_500 = operation["responses"].get("500")
            assert response_500 is not None
            schema = response_500["content"]["application/json"]["schema"]
            any_of = schema.get("anyOf", [])
            # Should have exactly 2 refs: ModelA and ModelB
            assert len(any_of) == 2, f"Expected 2 refs in anyOf, got {len(any_of)} for {path} {method}"

    print("Test passed!")

if __name__ == "__main__":
    test_openapi_duplication()

